@startuml

class Customer {
  + name : string
  + address : string
  + accountNumber : string
}

class Broker {
  + brokerId : int
  + name : string
  + contactNumber : string
}

class Contract {
  + contractId : int
  + signingDate : date
  + billingFrequency : string
  + totalPrice : double
}

class InsuranceProduct {
  + productId : int
  + productName : string
  + basePrice : double
}

class Offer {
  + offerId : int
  + expiryDate : date
  + status : string
}

class ClaimCase {
  + caseId : int
  + description : string
  + status : string
  + openingDate : datetime
}

class Estimator {
  + estimatorId : int
  + name : string
  + areaOfExpertise : string
}

class EstimatorReport {
  + reportId : int
  + findings : string
  + dateIssued : date
}

class CompensationDecision {
  + decisionId : int
  + isApproved : boolean
  + eligibleCosts : string
}

class Payment {
  + paymentId : int
  + amount : double
  + paymentDate : datetime
}

Customer "1" -- "0..*" Contract
Broker "1" -- "0..*" Customer : manages
Contract "0..*" -- "1" InsuranceProduct : covers
Contract "1" -- "0..*" Offer : generates
Customer "1" -- "0..*" Offer : receives
Customer "1" -- "0..*" ClaimCase : files
ClaimCase "1" *-- "1..*" EstimatorReport : contains
Estimator "1" -- "1..*" EstimatorReport : writes
ClaimCase "1" -- "0..1" CompensationDecision : resultsIn
CompensationDecision "1" -- "0..1" Payment : triggers

@enduml

